  // HEADLINE GENERATOR
  function generateHeadline(subject, mood) {
    if (mood === "chaotic") return subject + " is breaking apart";
    if (mood === "minimal") return subject;
    if (mood === "introspective") return "nothing about " + subject + " feels accidental";
    if (mood === "futuristic") return subject + " in the next state";
    return subject;
  }

  function generateSubhead(tone) {
    if (tone === "poetic") return "a quiet observation of movement";
    if (tone === "journalistic") return "a closer look at the process";
    return "a study in progression";
  }

  document.getElementById("headline").innerText =
    generateHeadline(input.subject, input.mood);

  document.getElementById("subhead").innerText =
    generateSubhead(input.tone);

  // SCROLL FADE-IN
  const faders = document.querySelectorAll(".fade");

  const appearOptions = {
    threshold: 0.2
  };

  const appearOnScroll = new IntersectionObserver(function(entries) {
    entries.forEach(entry => {
      if (!entry.isIntersecting) return;
      entry.target.classList.add("visible");
    });
  }, appearOptions);

  faders.forEach(fader => {
    appearOnScroll.observe(fader);
  });
